'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var abs = require( '@stdlib/math/base/special/abs' );
var EPS = require( '@stdlib/constants/float64/eps' );
var incrnanmae = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof incrnanmae, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns an accumulator function', function test( t ) {
	t.equal( typeof incrnanmae(), 'function', 'returns a function' );
	t.end();
});

tape( 'the initial accumulated value is `null`', function test( t ) {
	var acc = incrnanmae();
	t.equal( acc(), null, 'returns expected value' );
	t.end();
});

tape( 'the accumulator function incrementally computes the mean absolute error, ignoring NaN values', function test( t ) {
	var expected;
	var actual;
	var delta;
	var data;
	var acc;
	var sum;
	var tol;
	var N;
	var n;
	var x;
	var y;
	var i;

	data = [
		[ 2.0, 3.0 ],    // MAE = |2-3| / 1 = 1.0
		[ 3.0, NaN ],    // Ignored, MAE = 1.0
		[ NaN, 5.0 ],    // Ignored, MAE = 1.0
		[ 4.0, -4.0 ],   // MAE = (1 + |4-(-4)|) / 2 = 4.5
		[ NaN, NaN ],    // Ignored, MAE = 4.5
		[ -4.0, 5.0 ]    // MAE = (1 + 8 + |-4-5|) / 3 = 6.0
	];
	N = data.length;

	acc = incrnanmae();

	sum = 0;
	n = 0; // Count of valid pairs
	for ( i = 0; i < N; i++ ) {
		x = data[ i ][ 0 ];
		y = data[ i ][ 1 ];
		if ( !isnan( x ) && !isnan( y ) ) {
			sum += abs( y-x );
			n += 1;
			expected = sum / n;
		} else {
			expected = ( n === 0 ) ? null : sum / n;
		}
		actual = acc( x, y );
		if ( actual === expected ) {
			t.equal( actual, expected, 'returns expected value' );
		} else {
			delta = abs( expected - actual );
			tol = 1.0 * EPS * abs( expected );
			t.equal( delta <= tol, true, 'within tolerance. Actual: '+actual+'. Expected: '+expected+'. Delta: '+delta+'. Tol: '+tol+'.' );
		}
	}
	t.end();
});

tape( 'if not provided an input value, the accumulator function returns the current mean absolute error', function test( t ) {
	var data;
	var acc;
	var i;

	data = [
		[ 2.0, 3.0 ],    // MAE = 1.0
		[ NaN, -5.0 ],   // Ignored, MAE = 1.0
		[ 1.0, NaN ],    // Ignored, MAE = 1.0
		[ 1.0, 10.0 ]    // MAE = (1 + |1-10|) / 2 = 5.0
	];
	acc = incrnanmae();
	for ( i = 0; i < data.length; i++ ) {
		acc( data[ i ][ 0 ], data[ i ][ 1 ] );
	}
	t.equal( acc(), 5.0, 'returns expected value' );
	t.end();
});
